class Solution {
public:
    int strStr(string haystack, string needle) {
        int n = haystack.size(), m = needle.size();
        if (m == 0) return 0;
        if (m > n) return -1;
        const long long BASE = 256, MOD = 1000000007;
        long long power = 1;
        for (int i = 0; i < m - 1; ++i) power = (power * BASE) % MOD;
        long long needleHash = 0, windowHash = 0;
        for (int i = 0; i < m; ++i) {
            needleHash = (needleHash * BASE + (unsigned char)needle[i]) % MOD;
            windowHash = (windowHash * BASE + (unsigned char)haystack[i]) % MOD;
        }
        for (int i = 0; i <= n - m; ++i) {
            if (windowHash == needleHash && haystack.compare(i, m, needle) == 0) return i;
            if (i + m < n) {
                windowHash = (windowHash - (unsigned char)haystack[i] * power % MOD + MOD) % MOD;
                windowHash = (windowHash * BASE + (unsigned char)haystack[i + m]) % MOD;
            }
        }
        return -1;
    }
};

