class Solution {
    public int strStr(String haystack, String needle) {
        int n = haystack.length(), m = needle.length();
        if (m == 0) return 0;
        if (m > n) return -1;
        long BASE = 256, MOD = 1000000007;
        long power = 1;
        for (int i = 0; i < m - 1; i++) power = (power * BASE) % MOD;
        long needleHash = 0, windowHash = 0;
        for (int i = 0; i < m; i++) {
            needleHash = (needleHash * BASE + needle.charAt(i)) % MOD;
            windowHash = (windowHash * BASE + haystack.charAt(i)) % MOD;
        }
        for (int i = 0; i <= n - m; i++) {
            if (windowHash == needleHash) {
                if (haystack.substring(i, i + m).equals(needle)) return i;
            }
            if (i + m < n) {
                windowHash = (windowHash - haystack.charAt(i) * power % MOD + MOD) % MOD;
                windowHash = (windowHash * BASE + haystack.charAt(i + m)) % MOD;
            }
        }
        return -1;
    }
}
